std::uint32_t word(const std::uint8_t*p){return p[0]|std::uint32_t(p[1])<<8|std::uint32_t(p[2])<<16|std::uint32_t(p[3])<<24;}
bool text(const dh2::resources::BresView&v,std::uint32_t p,std::string&out,std::string&e){if(!p||p>=v.size){e="Required actual skybox serialized string";return false;}const auto*end=static_cast<const std::uint8_t*>(std::memchr(v.bytes+p,0,v.size-p));if(!end){e="Unterminated actual skybox string";return false;}out.assign(reinterpret_cast<const char*>(v.bytes+p),end-(v.bytes+p));return true;}
bool diffuse_uri(const dh2::resources::BresView&v,std::uint32_t material,std::string&out,std::string&e){
 const auto*p=dh2_bres_library_item(&v,dh2::resources::Library::material,material);if(!p){e="Actual skybox material absent";return false;}const auto count=word(p+16),base=word(p+20);if(std::uint64_t(base)+std::uint64_t(count)*24>v.size){e="Skybox material parameters outside BRES";return false;}
 for(unsigned i=0;i<count;++i){const auto*q=v.bytes+base+i*24;std::string name;if(!text(v,word(q),name,e))return false;if(name!="Diffuse"&&name!="diffuse-sampler")continue;
  if(word(q+8)!=11||word(q+12)!=1){e="Required actual scalar skybox texture sampler";return false;}const auto sizes=word(q+16),data=word(q+20);if(sizes+4ull>v.size||data+4ull>v.size||word(v.bytes+sizes)!=1){e="Invalid skybox sampler vector";return false;}const auto pointer=word(v.bytes+data);if(pointer+4ull>v.size){e="Invalid skybox sampler pointer";return false;}const auto image=word(v.bytes+pointer);const auto*img=dh2_bres_library_item(&v,dh2::resources::Library::image,image);if(!img){e="Skybox actual texture image index absent";return false;}return text(v,word(img+8),out,e);
 }e="Required reached skybox COMMON diffuse sampler producer";return false;
}
