bool GameplaySkyboxV24::add(const std::string&file,std::string&e){if(file.empty())return true;std::shared_ptr<SkyboxResourceV24>resource;bool found;if(!prepare(file,resource,found,e))return false;if(!found)return true;if(!services_.same_roots){e="Required SAME actual skybox SceneManager root registry";return false;}if(!services_.material_renderer){e="Required actual original COMMON skybox material renderer constructor";return false;}std::vector<SkyboxMaterialRendererBorrowV24> materials(resource->scene.materials.size());for(unsigned i=0;i<materials.size();++i)if(!services_.material_renderer(resource,i,materials[i],e))return false;
 // LoadScene constructs new mesh/materials before original old438 removal.
 // SkyBox wrapper C1 and its depth-write mutation follow that removal.
 if(skybox438_){if(!skybox438_->detach(e)||!skybox438_->drop(e))return false;skybox438_.reset();}auto node=std::make_shared<SkyboxNodeV24>(resource,std::move(materials),services_.same_roots);if(!node->construct_tail(e))return false;skybox438_=std::move(node);if(!skybox438_->attach(e))return false;reached_resource_.reset();return true;}
